def reviewbar(active):
    links = [('index', 'Review'), ('a', 'A / Registers'), ('b', 'B / Entities'), ('c', 'C / Slack')]
    nav = ''.join(f'<a href="{key}.html"'+ (' aria-current="page"' if key == active else '') + f'>{name}</a>' for key, name in links)
    return f'<header class="reviewbar"><strong>LEGAL OS / V2</strong><nav aria-label="Design options">{nav}</nav><span class="note">Static concepts · No live records</span></header>'


def shell(key, label, content):
    nav = [('repositories','Repositories'),('entities','Entities & KYC'),('reviews','Review triggers'),('disputes','Litigation & Arbitration'),('operations','Slack & access'),('backups','Backups & naming')]
    links=''.join(f'<a href="#{anchor}"'+(' class="active"' if anchor=={'a':'repositories','b':'entities','c':'operations'}[key] else '')+f'>{name}</a>' for anchor,name in nav)
    sidebar=f'<aside class="sidebar"><div><div class="brand">Legal<span> OS</span></div><small>League Sports Co</small></div><nav aria-label="Page sections">{links}</nav><footer>Design review<br>21 September 2026<br><br>All record values are unknown.<br>Preview controls do not send or export.</footer></aside>'
    return document(f'{label} | Legal OS v2',reviewbar(key)+f'<div class="shell">{sidebar}<main id="main" class="content"><div class="topline"><span>Legal workspace / <b>{label}</b></span><span>Reporting currency <b>USD</b></span></div><div class="page">{content}</div></main></div>')


def document(title, body):
    return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark"><title>{title}</title><link rel="stylesheet" href="styles.css"></head><body><a class="skip" href="#main">Skip to content</a>{body}</body></html>'


def title(name, sub, action='Download all'):
    return f'<div class="title"><div><h1>{name}</h1><p>{sub}</p></div><button class="btn" type="button" disabled title="Static preview only">{action} · Preview</button></div>'


summary='''<div class="summary"><div><span>Agreement value · USD</span><strong class="mono">Not loaded</strong><small>Verified FX required</small></div><div><span>Reviews due</span><strong>Not loaded</strong><small>Based on document schedules</small></div><div><span>Dispute exposure · USD</span><strong class="mono">Unknown</strong><small>Missing exposure stays unknown</small></div><div><span>Monthly export</span><strong>Not verified</strong><small>No completion receipt loaded</small></div></div>'''


def repositories(heading=True):
    return (('<div class="sectionhead"><h2>Document repositories</h2><span>Source, populated, signed</span></div>') if heading else '')+'''<div class="tabs" aria-label="Repository stages"><span class="selected">Templates</span><span>Populated templates</span><span>Signed versions</span></div><div class="tablewrap"><table><thead><tr><th>Document type</th><th>Arena / owner</th><th>Agreement value</th><th>Shared Drive</th></tr></thead><tbody><tr><td><strong>MNDA · Individual</strong><small>Template type; no record loaded</small></td><td>Unconfirmed<small>Owner initials required</small></td><td class="mono">Not applicable<small>Value belongs to agreement</small></td><td>Not verified</td></tr><tr><td><strong>MNDA · Business</strong><small>Template type; no record loaded</small></td><td>Unconfirmed<small>Owner initials required</small></td><td class="mono">Not applicable<small>Value belongs to agreement</small></td><td>Not verified</td></tr><tr><td><strong>[Populated agreement]</strong><small>Placeholder for signer and deliverables</small></td><td>[Arena code]<small>[Owner initials]</small></td><td class="mono">[Native amount]<small>(USD unavailable)</small></td><td>Excluded until final</td></tr></tbody></table></div><div class="lineage"><div><div class="step">01 / TEMPLATE</div><h3>Approved source</h3><p>Original file, approval and published final.</p></div><div><div class="step">02 / POPULATED</div><h3>Signer & deliverables</h3><p>Linked to the exact source template.</p></div><div><div class="step">03 / SIGNED</div><h3>Executed agreement</h3><p>Signed file, certificate and lineage.</p></div></div>'''


def entities(detailed=False):
    graphic='''<div class="graph" role="img" aria-label="Placeholder ownership diagram. Shareholder, company and ownership percentages are unconfirmed."><div class="graph-node"><strong>[Shareholder]</strong><small>Identity to confirm</small></div><div class="connector"></div><div class="graph-children"><div class="graph-node"><strong>[Legal entity]</strong><small>Holding % unknown</small></div><div class="graph-node"><strong>[Legal entity]</strong><small>Holding % unknown</small></div></div><p class="graph-caption">Placeholder relationships only. No ownership data supplied.</p></div>'''
    rows='''<div class="facts"><div class="fact"><span>Registration</span><p>Certificate, jurisdiction and expiry</p></div><div class="fact"><span>Annual reports</span><p>Filing, due date and receipt</p></div><div class="fact"><span>Registered agent / office</span><p>Appointment, address and renewal</p></div><div class="fact"><span>KYC</span><p>Entity documents and verification</p></div></div>'''
    return '<div class="sectionhead"><h2>Entities under Compliance</h2><span>Legal identities and arena codes stay separate</span></div>'+('<div class="two">'+graphic+rows+'</div>' if not detailed else '<div class="arena"><div class="arena-list">'+''.join(f'<span class="entity-choice">[Entity {label}]<small>Identity pending</small></span>' for label in ['A','B','C'])+'</div><div id="entity-record"><div class="sectionhead"><h3>[Legal entity record]</h3><span>Arena mapping unconfirmed</span></div>'+graphic+rows+'</div></div>')


def reviews():
    return '''<div class="sectionhead"><h2>Review triggers</h2><span>Due date, owner, evidence, completion</span></div><div class="tablewrap"><table><thead><tr><th>Document group</th><th>Cadence</th><th>Trigger basis</th><th>Next review</th></tr></thead><tbody><tr><td><strong>Public-facing documents</strong></td><td>Every 14 days</td><td>First six months from confirmed start</td><td class="warning">Start date required</td></tr><tr><td><strong>Policies & Procedures</strong><small>Internal, including record retention</small></td><td>4 to 6 months</td><td>Chosen per policy</td><td class="warning">Interval required</td></tr><tr><td><strong>Correlated documents</strong></td><td>On dependency change</td><td>Arvind's correlation table</td><td class="warning">Table required</td></tr></tbody></table></div>'''


def disputes():
    return '''<div class="sectionhead"><h2>Litigation & Arbitration</h2><span>Separate trackers, shared matter history</span></div><div class="two"><div><h3>Litigation</h3><div class="keyline"><span>Claim type / court</span><span>Not loaded</span></div><div class="keyline"><span>Plaintiff / defendant</span><span>Not loaded</span></div><div class="keyline"><span>Exposure</span><span class="mono">[Native amount] (USD unavailable)</span></div><div class="keyline"><span>Finance delivery</span><span>Not verified</span></div></div><div><h3>Arbitration</h3><div class="keyline"><span>Claim type / tribunal</span><span>Not loaded</span></div><div class="keyline"><span>Claimant / respondent</span><span>Not loaded</span></div><div class="keyline"><span>Exposure</span><span class="mono">[Native amount] (USD unavailable)</span></div><div class="keyline"><span>Finance delivery</span><span>Not verified</span></div></div></div><p class="notice">Unclassified existing matters remain visible for review. Unknown exposure is never counted as zero.</p>'''


def operations():
    return '''<div class="sectionhead"><h2>Slack operations & access</h2><span>90% operable from Slack is the target</span></div><div class="two"><div><div class="keyline"><span>Global document access</span><span>Four approved access identifiers</span></div><div class="keyline"><span>Other requesters</span><span>Request access through legal</span></div><div class="keyline"><span>Cross-drive retrieval</span><span>Permission check before results</span></div></div><div><div class="keyline"><span>Contract generation</span><span class="warning">Proposed pause until CLI ready</span></div><div class="keyline"><span>Required reviews</span><span>Fair clauses + independent review</span></div><div class="keyline"><span>Clause references</span><span>Checked before release</span></div></div></div>'''


def backups():
    return '''<div class="sectionhead"><h2>Backups & organization-wide naming</h2><button class="btn" type="button" disabled title="Static preview only">Download all · Preview</button></div><div class="two"><div><div class="keyline"><span>Platform storage</span><span>GCP; recovery coverage to verify</span></div><div class="keyline"><span>Shared Google Drive</span><span>Final versions only</span></div><div class="keyline"><span>Monthly manual export</span><span>Archive + manifest + receipt</span></div><p class="footnote">Export completeness and unavailable files must be visible.</p></div><div><div class="filename"><span>[Arena]</span>_[CAT]_[Full counterparty]_[DDMMMYYYY]_[Initials].[ext]</div><p class="footnote">FSP · WBL · WPS · TLC · TBRC · TBR<br>Three-letter category lexicon and date basis need confirmation. No version suffix. Internal history is retained.</p></div></div>'''


def section(key, content):
    return f'<section id="{key}" class="section">{content}</section>'


aside='''<aside class="aside"><h2>Document context</h2><div class="facts"><div class="fact"><span>Selection</span><p>[Agreement placeholder]</p></div><div class="fact"><span>Linked artifacts</span><p>Template → populated → signed</p></div><div class="fact"><span>Signer / deliverables</span><p>Not loaded</p></div><div class="fact"><span>Agreement currency</span><p class="mono">[Native amount] (USD unavailable)</p></div><div class="fact"><span>Next review</span><p>Not scheduled</p></div><div class="fact"><span>File publication</span><p>Final-only; receipt not verified</p></div></div></aside>'''
a=title('The legal register.','Documents first. Review context stays beside the record.')+summary+'<section id="repositories"><div class="sectionhead"><h2>Repositories</h2><div class="toolbar"><span>All arenas</span><label>Currency <select disabled aria-label="Preview currency filter"><option>All agreement currencies</option></select></label></div></div><div class="split"><div>'+repositories(False)+'</div>'+aside+'</div></section>'+section('entities',entities())+section('reviews',reviews())+section('disputes',disputes())+section('operations',operations())+section('backups',backups())
b=title('One entity. Every obligation.','Registrations, ownership, KYC and documents in one place.','Add entity')+'<section id="entities">'+entities(True)+'</section>'+section('reviews',reviews())+section('repositories',repositories())+section('disputes',disputes())+section('operations',operations())+section('backups',backups())
thread='''<div class="thread"><div class="threadhead"><strong># legal</strong><span>Proposed Slack flow</span></div><div class="message"><b>Requester</b><p class="command">Find the signed MNDA for [full counterparty].</p><div class="reply"><b>Autonomos</b><p>Check your document access before searching connected drives.</p><p class="warning">No grant loaded in this concept.</p><button class="btn" disabled title="No request is sent">Request legal access · Preview</button></div></div><div class="message"><b>Legal member</b><p class="command">Show public-document reviews due for [entity].</p><div class="reply"><b>Autonomos</b><p>Review schedule, owner and dependency changes appear together.</p><p>Results require entity records and Arvind's trigger table.</p></div></div><div class="compose"><span>Find a document, review a trigger, or check a matter...</span><span>Preview only</span></div></div>'''
queue='''<div><div class="sectionhead"><h2>Decisions requiring legal</h2><span>Proposed workflow types</span></div><div class="queueitem"><div class="meta">ACCESS / DOCUMENT REQUEST</div><h3>Approve a scoped request</h3><p>Requester, purpose and document scope. Four approved access identifiers hold global access.</p></div><div class="queueitem"><div class="meta">REVIEW / DEPENDENCY CHANGE</div><h3>Review the affected documents</h3><p>Trace the triggering change, assign an owner and record completion evidence.</p></div><div class="queueitem"><div class="meta">GENERATION / PAUSE</div><h3>Claude CLI integration pending</h3><p>Authentication, review agent and cross-reference checks must pass before activation.</p></div><div class="queueitem"><div class="meta">BACKUP / MONTHLY</div><h3>Download and verify the export</h3><p>Keep the manifest, archive and completion receipt together.</p></div></div>'''
c=title('Legal work, from Slack.','The dashboard keeps records, exceptions and evidence within reach.','Open Slack')+'<section id="operations"><div class="ops">'+thread+queue+'</div></section>'+section('repositories',repositories())+section('entities',entities())+section('reviews',reviews())+section('disputes',disputes())+section('backups',backups())

index=reviewbar('index')+'''<main id="main" class="index"><h1>Legal OS v2.<br>Three ways to work.</h1><p class="intro">Choose the primary workspace. Each direction keeps the same near-black shell, three document repositories, entity records, separate dispute trackers and auditable workflows.</p><a class="option" href="a.html"><span class="letter">A</span><div><h2>Registers first</h2><p>A dense document register with a context panel. Fast to scan, straightforward to audit, and closest to the existing dashboard.</p><span class="recommended">RECOMMENDED FOUNDATION</span></div><span class="go">Explore direction A →</span></a><a class="option" href="b.html"><span class="letter">B</span><div><h2>Entities first</h2><p>Start with the entity, then inspect ownership, registration, KYC, obligations and documents in the same workspace.</p></div><span class="go">Explore direction B →</span></a><a class="option" href="c.html"><span class="letter">C</span><div><h2>Slack first</h2><p>A command flow beside legal decisions. Use the dashboard to resolve exceptions and inspect the evidence behind actions.</p></div><span class="go">Explore direction C →</span></a><p class="notice"><strong>Design review only.</strong> These are static layout options. No records are loaded, no messages are sent, no downloads run, and no production settings change.</p><p class="footnote">Prepared 21 September 2026. <a href="scope.html">Read scope and implementation boundaries</a>.</p></main>'''
scope=reviewbar('index')+'''<main id="main" class="index"><h1>Scope & boundaries.</h1><p class="intro">The approved direction will be implemented in small, independently verified changes. These concepts are not the live application.</p><div class="keyline"><span>Repositories</span><span>Template, populated per signer/deliverables, signed; internal history retained</span></div><div class="keyline"><span>Currency</span><span>USD reporting default; native agreement amount with USD reference</span></div><div class="keyline"><span>Entities</span><span>Registration, annual reports, agent/office, ownership, KYC</span></div><div class="keyline"><span>Reviews</span><span>14 days for first six months; internal policies every 4 to 6 months</span></div><div class="keyline"><span>Disputes</span><span>Litigation and Arbitration; sourced exposure delivered to Finance</span></div><div class="keyline"><span>Generation</span><span>Pause first; Claude CLI authentication and required reviews before activation</span></div><div class="keyline"><span>Access</span><span>Four approved access identifiers globally; others request scoped access</span></div><div class="keyline"><span>Files</span><span>Finals only in shared Drive; organization-wide lexicon; monthly manual export</span></div><p class="notice">Inputs still required: Workspace identity types, Slack IDs, mailbox delegation mode, Drive destinations, category lexicon, arena mappings, naming date basis, verified FX source, ownership evidence and Arvind's dependency table. The four access emails are confirmed. The calendar follow-up was removed from scope.</p><p class="footnote">Source review found incomplete Finance exposure delivery, API-based generation, and currency aggregation issues. Live runtime, backups and mailbox permissions have not been verified.</p><p class="footnote"><a href="index.html">← Return to the three directions</a></p></main>'''

(output/'styles.css').write_text(styles)
for key, content in [('a',shell('a','Registers first',a)),('b',shell('b','Entities first',b)),('c',shell('c','Slack first',c)),('index',document('Legal OS v2 | Design review',index)),('scope',document('Legal OS v2 | Scope',scope))]:
    (output/f'{key}.html').write_text(content)
